#!/usr/bin/env python3
"""Print the next 5 fire times of a 5-field cron expression after an ISO datetime.

Usage: cronnext.py "<cron expr>" "<ISO datetime>"
"""

import sys
from dataclasses import dataclass
from datetime import datetime, timedelta

FIELD_NAMES = ("minute", "hour", "day-of-month", "month", "day-of-week")
FIELD_RANGES = {
    "minute": (0, 59),
    "hour": (0, 23),
    "day-of-month": (1, 31),
    "month": (1, 12),
    "day-of-week": (0, 6),  # 0 = Sunday
}

WEEKDAY_NAMES = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


class CronError(ValueError):
    pass


@dataclass(frozen=True)
class Field:
    values: frozenset


def _parse_atom(atom: str, lo: int, hi: int, field: str) -> set:
    """Parse one comma-separated element: N, N-M, */S, N-M/S, or N/S."""
    step = 1
    base = atom
    if "/" in atom:
        base, _, step_str = atom.partition("/")
        if not step_str.isdigit():
            raise CronError(f"{field}: invalid step '{step_str}'")
        step = int(step_str)
        if step < 1:
            raise CronError(f"{field}: step must be >= 1")

    if base == "*":
        start, end = lo, hi
    elif "-" in base:
        a, _, b = base.partition("-")
        if not a.isdigit() or not b.isdigit():
            raise CronError(f"{field}: invalid range '{base}'")
        start, end = int(a), int(b)
        if start > end:
            raise CronError(f"{field}: inverted range '{base}'")
    else:
        if not base.isdigit():
            raise CronError(f"{field}: invalid number '{base}'")
        start = int(base)
        # N with a step means N..hi; plain N means just N.
        end = hi if "/" in atom else start

    if start < lo or end > hi:
        raise CronError(
            f"{field}: value out of range {lo}-{hi} in '{atom}'"
        )
    return list(range(start, end + 1, step))


def parse_field(spec: str, field: str) -> Field:
    lo, hi = FIELD_RANGES[field]
    values: set = set()
    for atom in spec.split(","):
        if not atom:
            raise CronError(f"{field}: empty element in '{spec}'")
        values.update(_parse_atom(atom, lo, hi, field))
    return Field(frozenset(values))


def _dow_to_python_weekday(v: int) -> int:
    """Cron 0=Sunday..6=Saturday -> Python Monday=0..Sunday=6."""
    return 6 if v == 0 else v - 1


def parse_cron(expr: str):
    parts = expr.split()
    if len(parts) != 5:
        raise CronError(f"expected 5 fields, got {len(parts)}")
    minute = parse_field(parts[0], "minute")
    hour = parse_field(parts[1], "hour")
    dom = parse_field(parts[2], "day-of-month")
    month = parse_field(parts[3], "month")
    dow = parse_field(parts[4], "day-of-week")
    dom_restricted = parts[2] != "*"
    dow_restricted = parts[4] != "*"
    both_restricted = dom_restricted and dow_restricted
    dow_py = frozenset(_dow_to_python_weekday(v) for v in dow.values)
    return minute, hour, dom, month, dow_py, both_restricted


def matches(cron_parts, dt: datetime) -> bool:
    minute, hour, dom, month, dow_py, both_restricted = cron_parts
    if dt.minute not in minute.values:
        return False
    if dt.hour not in hour.values:
        return False
    if dt.month not in month.values:
        return False
    day_dom = dt.day in dom.values
    day_dow = dt.weekday() in dow_py
    if both_restricted:
        # Classic vixie-cron quirk: fire when either DOM or DOW matches.
        return day_dom or day_dow
    if dom_restricted := (dom.values != frozenset(range(1, 32))):
        return day_dom
    if dow_py != frozenset(range(7)):
        return day_dow
    return True


def next_fires(expr: str, start: datetime, count: int = 5):
    cron_parts = parse_cron(expr)
    t = (start + timedelta(minutes=1)).replace(second=0, microsecond=0)
    found = []
    while len(found) < count:
        if matches(cron_parts, t):
            found.append(t)
        t += timedelta(minutes=1)
    return found


def main(argv):
    if len(argv) != 3:
        print("usage: cronnext.py '<cron expr>' '<ISO datetime>'", file=sys.stderr)
        return 2
    try:
        fires = next_fires(argv[1], datetime.fromisoformat(argv[2]))
    except CronError as e:
        print(f"error: {e}", file=sys.stderr)
        return 2
    except ValueError as e:
        print(f"error: bad datetime: {e}", file=sys.stderr)
        return 2
    for f in fires:
        print(f.isoformat())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

